begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temp table market_ids(actor text,id uuid);
insert into market_ids values('seller','11111111-1111-4111-8111-111111111111'),('buyer','22222222-2222-4222-8222-222222222222'),('other','33333333-3333-4333-8333-333333333333'),('admin','44444444-4444-4444-8444-444444444444');
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select id,'authenticated','authenticated',actor||'@market-test.invalid','',now(),'{}','{}',now(),now() from market_ids;
insert into public.user_roles(user_id,role_id) select (select id from market_ids where actor='admin'),id from public.roles where key='super_admin' on conflict do nothing;
insert into public.market_stores(id,owner_id,name,slug,status) values
 ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select id from market_ids where actor='seller'),'Fixture seller','fixture-seller','submitted'),
 ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',(select id from market_ids where actor='other'),'Fixture other','fixture-other','approved');
grant select on market_ids to authenticated;
set local role anon;
select is((select count(*) from public.market_stores where slug like 'fixture-%'),1::bigint,'anon sees approved stores only');
select throws_ok('select owner_id from public.market_stores','42501',null,'anon cannot query store owner identity');
select throws_ok('select * from public.market_listing_submissions','42501',null,'anon cannot query draft listings');
select throws_ok('select * from public.market_quote_requests','42501',null,'anon cannot query private quotation contacts');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='seller'),true);
set local role authenticated;
select throws_ok($q$update public.market_stores set status='approved' where slug='fixture-seller'$q$,'42501',null,'seller cannot self-approve storefront');
select throws_ok($q$insert into public.market_listing_submissions(store_id,name,stock) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Fixture listing',5)$q$,'42501',null,'submitted store cannot publish a listing request');
select throws_ok($q$select public.market_review_listing('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',true,'')$q$,'P0001','ADMIN_REQUIRED','seller cannot call publication as admin');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='admin'),true);
set local role authenticated;
select lives_ok($q$update public.market_stores set status='approved' where slug='fixture-seller'$q$,'admin can approve storefront');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='seller'),true);
set local role authenticated;
select lives_ok($q$insert into storage.objects(bucket_id,name) values('market-media','market/11111111-1111-4111-8111-111111111111/fixture.png')$q$,'approved seller may upload into own media folder');
select throws_ok($q$insert into storage.objects(bucket_id,name) values('market-media','market/33333333-3333-4333-8333-333333333333/fixture.png')$q$,'42501',null,'seller cannot upload to another media folder');
select lives_ok($q$insert into public.market_listing_submissions(id,store_id,name,description,price_dzd,stock,minimum_order)
 values('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Fixture market item','Testing only',100,5,2)$q$,'approved seller can submit product');
select throws_ok($q$insert into public.market_listing_submissions(store_id,name,stock) values('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','Foreign store item',1)$q$,'42501',null,'seller cannot submit to another store');
select throws_ok($q$insert into public.market_listing_submissions(store_id,name,images) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Unsafe URL','["javascript:alert(1)"]')$q$,'23514',null,'direct Data API cannot submit script image URL');
select throws_ok($q$update public.market_listing_submissions set status='approved' where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'$q$,'42501',null,'seller cannot self-approve product');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='other'),true);
set local role authenticated;
select is((select count(*) from public.market_listing_submissions where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'),0::bigint,'other seller cannot read private listing');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='admin'),true);
set local role authenticated;
select lives_ok($q$select public.market_review_listing('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',true,'Approved fixture')$q$,'admin atomically publishes reviewed product');
select is((select status from public.market_listing_submissions where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'),'approved','approval persists submission state');
select is((select count(*) from public.products where slug='partner-eeeeeeeeeeee4eee8eeeeeeeeeeeeeee'),1::bigint,'exactly one catalogue product created');
select is((select quantity_on_hand from public.inventory_items where product_id=(select product_id from public.market_listing_submissions where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee')),5,'published inventory is configured');
select lives_ok($q$select public.market_review_listing('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',true,'Retry')$q$,'repeat approval is idempotent');
select is((select count(*) from public.products where slug='partner-eeeeeeeeeeee4eee8eeeeeeeeeeeeeee'),1::bigint,'approval retry does not duplicate product');
reset role;
create temp table market_product_ids as select product_id from public.market_listing_submissions where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee';
grant select on market_product_ids to authenticated;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='buyer'),true);
set local role authenticated;
select throws_ok($q$select public.market_add_cart_item((select product_id from market_product_ids),1,false)$q$,'P0001','MINIMUM_ORDER_REQUIRED','cart rejects quantity below product minimum');
select lives_ok($q$select public.market_add_cart_item((select product_id from market_product_ids),2,false)$q$,'customer can add reviewed product to own cart');
select lives_ok($q$select public.market_add_cart_item((select product_id from market_product_ids),1,false)$q$,'second add increments quantity');
select is((select quantity from public.cart_items where product_id=(select product_id from market_product_ids)),3,'cart adds do not overwrite previous quantity');
select throws_ok($q$select public.market_add_cart_item((select product_id from market_product_ids),9,false)$q$,'P0001','INSUFFICIENT_STOCK','cart rejects quantity beyond current stock');
select lives_ok($q$select public.market_add_cart_item((select product_id from market_product_ids),2,true)$q$,'explicit quantity change replaces quantity');
select is((select quantity from public.cart_items where product_id=(select product_id from market_product_ids)),2,'replacement quantity persists');
select lives_ok($q$insert into public.market_quote_requests(id,customer_id,product_id,store_id,request_type,quantity,contact_name,contact_phone,message)
 select 'ffffffff-ffff-4fff-8fff-ffffffffffff',auth.uid(),product_id,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','wholesale',5,'Fixture buyer','0550000000','Fixture request only' from market_product_ids$q$,'customer can send scoped quote request');
select throws_ok($q$insert into public.market_quote_requests(customer_id,product_id,store_id,request_type,quantity,contact_name,contact_phone,message)
 select auth.uid(),product_id,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','wholesale',5,'Fixture buyer','0550000000','Fixture request only' from market_product_ids$q$,'42501',null,'customer cannot misroute product quote to another store');
select lives_ok($q$select public.checkout_active_cart('MARKET-FIXTURE-ORDER','{"recipient_name":"Fixture Buyer","phone":"0550000000","wilaya":"Fixture","address":"Fixture address only"}'::jsonb)$q$,'reviewed partner product completes existing checkout');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='other'),true);
set local role authenticated;
select is((select count(*) from public.market_seller_orders()),0::bigint,'other seller cannot read order delivery fields');
select is((select count(*) from public.market_quote_requests where id='ffffffff-ffff-4fff-8fff-ffffffffffff'),0::bigint,'unrelated seller cannot read buyer contact details');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='seller'),true);
set local role authenticated;
select is((select count(*) from public.market_seller_orders()),1::bigint,'responsible seller sees own product order line');
select is((select product_name from public.market_seller_orders() limit 1),'Fixture market item','seller order line names own product');
select is((select delivery->>'recipient_name' from public.market_seller_orders() limit 1),'Fixture Buyer','responsible seller sees delivery recipient');
select is((select count(*) from public.market_quote_requests where id='ffffffff-ffff-4fff-8fff-ffffffffffff'),1::bigint,'responsible seller sees own store inquiry');
select lives_ok($q$update public.market_quote_requests set status='answered',reply='Fixture response' where id='ffffffff-ffff-4fff-8fff-ffffffffffff'$q$,'seller can respond to own inquiry');
select throws_ok($q$update public.market_quote_requests set customer_id=auth.uid() where id='ffffffff-ffff-4fff-8fff-ffffffffffff'$q$,'42501',null,'seller cannot reassign customer identity');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='admin'),true);
set local role authenticated;
select lives_ok($q$update public.market_stores set status='suspended' where slug='fixture-seller'$q$,'admin can suspend store');
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select is((select count(*) from public.market_stores where slug='fixture-seller'),0::bigint,'suspended store disappears from public directory');
select is((select count(*) from public.products where slug='partner-eeeeeeeeeeee4eee8eeeeeeeeeeeeeee'),0::bigint,'suspended storefront product disappears from catalogue');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from market_ids where actor='buyer'),true);
set local role authenticated;
select throws_ok($q$select public.market_add_cart_item((select product_id from market_product_ids),2,false)$q$,'P0001','PRODUCT_NOT_AVAILABLE','suspended product cannot be added to cart');
reset role;
select * from finish();
rollback;
